def evaluate(current_reputation, observation, my_history, round_num):
    # Exponential moving average: blend current reputation with new observation.
    # Use different learning rates depending on action and reputation sign.
    alpha = 0.2  # base learning rate
    if observation['action'] == 'donate':
        target = 1.0
    else:
        target = -1.0
    # If reputation is already near the target, use a smaller update to avoid overshooting.
    if current_reputation * target > 0.5:  # same sign and magnitude >0.5
        alpha = 0.05
    elif abs(current_reputation) > 0.9:
        alpha = 0.02  # very extreme, change very slowly
    new_reputation = (1 - alpha) * current_reputation + alpha * target
    return max(-1.0, min(1.0, new_reputation))


def decide(recipient_reputation, round_num, my_history):
    # Base threshold that increases with round: start at -0.5, go to 0.5 by round 100.
    base_threshold = -0.5 + (round_num / 100.0) * 1.0
    base_threshold = max(-0.5, min(0.5, base_threshold))

    # Personal history: if we have donated less than 40% recently (last 10 actions),
    # become more cautious (raise threshold).
    recent_window = min(10, len(my_history))
    if recent_window >= 5:
        recent_donations = sum(1 for d in my_history[-recent_window:] if d)
        recent_rate = recent_donations / recent_window
        if recent_rate < 0.4:
            base_threshold += 0.3  # become stingy
        elif recent_rate > 0.7:
            base_threshold -= 0.2  # become generous

    # Additionally, if recipient reputation is very high (>0.8), donate regardless of threshold.
    if recipient_reputation > 0.8:
        return True
    # If recipient reputation is very low (<-0.8), never donate.
    if recipient_reputation < -0.8:
        return False

    return recipient_reputation > base_threshold

